local({
  s <- as.numeric(haven::zap_labels(SDEses_score))
  s <- if_else(s >= 3 & s <= 21, s, NA_real_)
  case_when(
    is.na(s) ~ "Unknown",
    s <= stats::quantile(s, 0.4, na.rm = TRUE) ~ "Low",
    s <= stats::quantile(s, 0.6, na.rm = TRUE) ~ "Medium",
    .default = "High"
  )
})

local({
  tv <- coalesce(as.numeric(MNEfernzim), as.numeric(MNfernzim))
  pc <- coalesce(as.numeric(MNEpczim), as.numeric(MNpczim))
  case_when(tv %in% 1 | pc %in% c(1, 2) ~ "TRUE", tv %in% 2 | pc %in% 3 ~ "FALSE", .default = NA_character_)
})
